//! Tree-sitter grammar for Colony Shell (rust-sitter)
//!
//! This crate provides a pure Rust Tree-sitter parser for Colony Shell syntax.
//! Generated using rust-sitter - no C code, no FFI, just Rust.
//!
//! Used for editor features like syntax highlighting, folding, and navigation.
//! For execution, use colony-parser (Pest or hand-written).

// Include the rust-sitter generated parser module
// This will be generated by: rust-sitter generate --rust-package-info Cargo.toml
mod parser;

pub use parser::language;

/// Content of the highlights query
pub const HIGHLIGHTS_QUERY: &str = include_str!("../../../queries/highlights.scm");

/// Parse source code and return a tree
pub fn parse(source: &str) -> Result<tree_sitter::Tree, tree_sitter::LanguageError> {
    let mut parser = tree_sitter::Parser::new();
    parser.set_language(language())?;
    parser.parse(source, None)
        .ok_or(tree_sitter::LanguageError::default())
}

/// Parse source code incrementally with old tree
pub fn parse_incremental(
    source: &str,
    old_tree: &tree_sitter::Tree,
) -> Result<tree_sitter::Tree, tree_sitter::LanguageError> {
    let mut parser = tree_sitter::Parser::new();
    parser.set_language(language())?;
    parser.parse(source, Some(old_tree))
        .ok_or(tree_sitter::LanguageError::default())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    #[ignore] // Until rust-sitter generates the parser module
    fn test_can_load_grammar() {
        let lang = language();
        assert!(lang.version() > 0);
    }

    #[test]
    #[ignore] // Until rust-sitter generates the parser module
    fn test_parse_simple_command() {
        let tree = parse("echo hello world").unwrap();
        let root = tree.root_node();

        assert_eq!(root.kind(), "program");
        assert!(root.child_count() > 0);
    }

    #[test]
    #[ignore] // Until rust-sitter generates the parser module
    fn test_parse_pipeline() {
        let tree = parse("echo foo | grep f").unwrap();
        let root = tree.root_node();

        assert_eq!(root.kind(), "program");
        assert!(root.child_count() > 0);
    }

    #[test]
    #[ignore] // Until rust-sitter generates the parser module
    fn test_incremental_parse() {
        let tree1 = parse("echo hello").unwrap();
        let tree2 = parse_incremental("echo world", &tree1).unwrap();

        assert_eq!(tree1.root_node().kind(), "program");
        assert_eq!(tree2.root_node().kind(), "program");
    }
}
